-- Restrict logo writes to an active Promoteur with an active link to an active pharmacy.
-- Existing policies are untouched. Public reads are served by the existing public bucket.
do $$ begin
 if not exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='promoteur_pharmacy_logo_insert') then create policy promoteur_pharmacy_logo_insert on storage.objects for insert to authenticated with check (bucket_id='pharmacies-photos' and split_part(name,'/',1)='logos' and exists(select 1 from public.profiles p join public.promoteur_pharmacies pp on pp.promoteur_id=p.id and pp.actif is true join public.pharmacies ph on ph.id=pp.pharmacie_id and ph.actif is true where p.id=auth.uid() and p.role='promoteur'::public.role_type and p.actif is true and pp.pharmacie_id::text=split_part(name,'/',2))); end if;
 if not exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='promoteur_pharmacy_logo_update') then create policy promoteur_pharmacy_logo_update on storage.objects for update to authenticated using (bucket_id='pharmacies-photos' and split_part(name,'/',1)='logos' and exists(select 1 from public.profiles p join public.promoteur_pharmacies pp on pp.promoteur_id=p.id and pp.actif is true join public.pharmacies ph on ph.id=pp.pharmacie_id and ph.actif is true where p.id=auth.uid() and p.role='promoteur'::public.role_type and p.actif is true and pp.pharmacie_id::text=split_part(name,'/',2))) with check (bucket_id='pharmacies-photos' and split_part(name,'/',1)='logos' and exists(select 1 from public.profiles p join public.promoteur_pharmacies pp on pp.promoteur_id=p.id and pp.actif is true join public.pharmacies ph on ph.id=pp.pharmacie_id and ph.actif is true where p.id=auth.uid() and p.role='promoteur'::public.role_type and p.actif is true and pp.pharmacie_id::text=split_part(name,'/',2))); end if;
 if not exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='promoteur_pharmacy_logo_delete') then create policy promoteur_pharmacy_logo_delete on storage.objects for delete to authenticated using (bucket_id='pharmacies-photos' and split_part(name,'/',1)='logos' and exists(select 1 from public.profiles p join public.promoteur_pharmacies pp on pp.promoteur_id=p.id and pp.actif is true join public.pharmacies ph on ph.id=pp.pharmacie_id and ph.actif is true where p.id=auth.uid() and p.role='promoteur'::public.role_type and p.actif is true and pp.pharmacie_id::text=split_part(name,'/',2))); end if;
end $$;
